pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint depositAmount, uint cashOutAmount) public {
        vm.assume(depositAmount < 1 ether);
        vm.assume(cashOutAmount <= depositAmount);
        vm.assume(caller != address(0));
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool depositSuccess,) = address(c).call{value: depositAmount}("");
        depositSuccess; // suppress warning
        // Deposit will not execute in reference if depositAmount < MinDeposit (1 ether)
        // Deposit will execute in mutant if depositAmount < 1 ether
        vm.prank(caller);
        c.CashOut(cashOutAmount);
        uint balanceAfter = c.balances(caller);
