pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound inputs to avoid excessive gas
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 0.5 ether, 10 ether);
        withdrawAmount = bound(withdrawAmount, 0, 10 ether);

        // Initial balance of contract
        uint256 initialBalance = address(c).balance;

        // Deposit via caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool depositOk,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Deposit()"));

        // Track how much was actually deposited (if deposit succeeded)
        uint256 actualDeposit = (depositAmount > c.MinDeposit()) ? depositAmount : 0;

        // Now CashOut
        vm.prank(caller);
        (bool cashOk,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // After CashOut, the sum of all balances should be <= contract balance (which is initial + actualDeposit - withdrawn amount if cashOk)
        uint256 finalContractBalance = address(c).balance;

        // We cannot directly read sum of all balances, but we know contract balance includes unaccounted ether (if any) and the balance mapping
        // However the invariant we assert: after any sequence, the total ether held by the contract (address(c).balance) is at least the sum of all balances[] (which we can read via the getter for one address? Not directly). 
        // Instead, a simpler invariant: after a CashOut, the contract balance should be >= the balance of the caller (since caller may have withdrawn but others still hold). But we can only check for the caller's balance.
        uint256 callersBalance = c.balances(caller);
        assertTrue(address(c).balance >= callersBalance);
    }
}

