pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount >= 1 ether && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount <= 1000 ether);

        // Initial sum of balances is 0
        uint256 sumBefore = c.balances(caller);

        // Deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Attempt withdrawal
        bool reverted;
        vm.prank(caller);
        try c.CashOut(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Sum after withdrawal
        uint256 sumAfter = c.balances(caller);

        // General rule: if withdrawal succeeded, sum should decrease by exactly withdrawAmount
        // If it reverted, sum should stay the same
        assertTrue(reverted ? sumAfter == sumBefore + depositAmount : sumAfter == (sumBefore + depositAmount) - withdrawAmount);
    }
}

