        // Rule: If CashOut succeeded, then the sum of contract balance and caller balance is unchanged
        if (success) {
            uint256 contractBalanceAfter = address(c).balance;
            uint256 callerBalanceAfter = caller.balance;
            assertTrue(contractBalanceBefore + callerBalanceBefore == contractBalanceAfter + callerBalanceAfter);
        } else {
            // If it reverted, we consider the property trivially true
            assertTrue(true);
        }
    }
}

